/**
 * Glosario del Título A de la NSR-10 (Capítulo A.13, págs. impresas A-125 a A-139; PDF 168–182).
 *
 * - `definiciones`: TODAS las definiciones de A.13.1, con el texto de la norma (solo se normalizó la
 *   puntuación que el PDF deja separada por las variables en cursiva y se reescribieron `m/s2` como `m/s²`).
 *   El `tema` y la `seccionRelacionada` son aportes editoriales para filtrar y enlazar; no vienen del PDF
 *   salvo cuando la propia definición cita la sección.
 * - `simbolos`: TODA la nomenclatura de A.13.2, verificada contra la imagen de las páginas A-135 a A-138
 *   (la extracción de texto del PDF revuelve columnas y pierde subíndices/fracciones).
 *
 * Notación tipográfica de `simbolo` y `significado`: `x_{sub}` subíndice, `x^{sup}` superíndice;
 * un `̄` tras la letra indica barra superior. Usa {@link textoPlano} para quitar el marcado.
 */

export type TemaGlosario =
  | 'amenaza-suelo'
  | 'sistema-estructural'
  | 'analisis-fuerzas'
  | 'deriva-separacion'
  | 'no-estructurales'
  | 'existentes'
  | 'profesionales-proceso'
  | 'cargas-unidades';

export const TEMAS_GLOSARIO: readonly { id: TemaGlosario; nombre: string; descripcion: string }[] = [
  { id: 'amenaza-suelo', nombre: 'Amenaza, suelo y uso', descripcion: 'Sismos, fallas, suelo, microzonificación, grupos de uso e infraestructura esencial.' },
  { id: 'sistema-estructural', nombre: 'Sistema estructural y comportamiento', descripcion: 'Pórticos, muros, diafragmas, ductilidad, disipación de energía (R, DES, DMO, DMI).' },
  { id: 'analisis-fuerzas', nombre: 'Análisis y fuerzas', descripcion: 'Espectros, modos de vibración, métodos de análisis, cortantes y efectos P-Delta.' },
  { id: 'deriva-separacion', nombre: 'Deriva y separación', descripcion: 'Pisos, alturas, derivas y separación sísmica entre edificaciones colindantes.' },
  { id: 'no-estructurales', nombre: 'Elementos no estructurales', descripcion: 'Acabados, muros divisorios, apéndices y grados de desempeño.' },
  { id: 'existentes', nombre: 'Existentes, vulnerabilidad y riesgo', descripcion: 'Sismo de seguridad limitada, vulnerabilidad y riesgo sísmico.' },
  { id: 'profesionales-proceso', nombre: 'Profesionales y proceso', descripcion: 'Diseñadores, revisor, constructor, supervisor técnico, licencia y propietario.' },
  { id: 'cargas-unidades', nombre: 'Cargas, masa y unidades', descripcion: 'Cargas, masa, peso, solicitaciones y el Sistema Internacional de Medidas.' },
];

export type Definicion = {
  termino: string;
  definicion: string;
  tema: TemaGlosario;
  /** Sección, capítulo o apéndice donde se desarrolla el concepto (A.x.y, A-3, B.2.1…). */
  seccionRelacionada?: string;
};

export type Simbolo = {
  /** Símbolo con marcado `_{}` y `^{}` (ver cabecera del archivo). */
  simbolo: string;
  significado: string;
  /** Sección(es) a las que remite la propia nomenclatura. */
  ref?: string;
};

/** Quita el marcado tipográfico (`_{}`, `^{}`) y deja el texto plano. */
export const textoPlano = (s: string): string => s.replace(/[_^]\{([^}]*)\}/g, '$1');

const colador = new Intl.Collator('es', { sensitivity: 'base', ignorePunctuation: true });

const DEFINICIONES_SIN_ORDEN: Definicion[] = [
  { termino: "Acabados", definicion: "Partes y componentes de una edificación que no hacen parte de la estructura o de su cimentación. Véase elementos no estructurales", tema: "no-estructurales" },
  { termino: "Aceleración pico efectiva, Aa", definicion: "Es un parámetro utilizado para determinar el espectro de diseño y se da en A.2.2.", tema: "amenaza-suelo", seccionRelacionada: "A.2.2" },
  { termino: "Acelerograma", definicion: "Descripción en el tiempo de las aceleraciones a que estuvo sometido el terreno durante la ocurrencia de un sismo real.", tema: "amenaza-suelo", seccionRelacionada: "A.2.7" },
  { termino: "Acelerógrafo", definicion: "Instrumento que permite registrar las aceleraciones a que se ve sometido el terreno durante la ocurrencia de un sismo. Este registro queda consignado en un acelerograma.", tema: "amenaza-suelo" },
  { termino: "Altura de la edificación en la colindancia", definicion: "Es la suma de las alturas de piso en la colindancia.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Altura del piso", definicion: "Es la distancia vertical medida entre el terminado de la losa de piso o de nivel de terreno y el terminado de la losa del nivel inmediatamente superior. En el caso que el nivel inmediatamente superior corresponda a la cubierta de la edificación esta medida se llevará hasta el nivel de enrace de la cubierta cuando esta sea inclinada o hasta al nivel de la impermeabilización o elemento de protección contra la intemperie cuando la cubierta sea plana. En los casos en los cuales la altura de piso medida como se indica anteriormente exceda 6 m, se considerará para efectos de calcular el número de pisos como dos pisos. Se permite que para el primer piso aéreo la altura del piso se mida desde la corona del muro de contención de la edificación nueva contra el paramento que está en la colindancia, cuando éste exista.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Amenaza sísmica", definicion: "Es el valor esperado de futuras acciones sísmicas en el sitio de interés y se cuantifica en términos de una aceleración horizontal del terreno esperada, que tiene una probabilidad de excedencia dada en un lapso de tiempo predeterminado.", tema: "amenaza-suelo", seccionRelacionada: "A.2.2" },
  { termino: "Amortiguamiento", definicion: "Pérdida de energía en un movimiento ondulatorio.", tema: "analisis-fuerzas" },
  { termino: "Amplificación de la onda sísmica", definicion: "Aumento en la amplitud de las ondas sísmicas, producido por su paso desde la roca hasta la superficie del terreno a través de los estratos de suelo.", tema: "amenaza-suelo", seccionRelacionada: "A.2.4" },
  { termino: "Análisis dinámico", definicion: "Procedimiento matemático por medio del cual se resuelven las ecuaciones de equilibrio dinámico, con el fin de obtener las deformaciones y esfuerzos de la estructura al ser sometida a una excitación que varía en el tiempo.", tema: "analisis-fuerzas", seccionRelacionada: "A.5" },
  { termino: "Análisis dinámico elástico", definicion: "Tipo de análisis dinámico en el cual las propiedades de rigidez y resistencia de la estructura permanecen dentro del rango de respuesta lineal.", tema: "analisis-fuerzas", seccionRelacionada: "A.5.4" },
  { termino: "Análisis dinámico inelástico", definicion: "Tipo de análisis dinámico en el cual se tiene en cuenta que las propiedades de rigidez y resistencia de la estructura pueden salirse del rango de respuesta lineal y entrar en el rango de respuesta inelástica.", tema: "analisis-fuerzas", seccionRelacionada: "A.5" },
  { termino: "Análisis espectral", definicion: "Tipo de análisis dinámico modal en el cual la respuesta dinámica máxima de cada modo se obtiene utilizando la ordenada del espectro, correspondiente al período de vibración del modo.", tema: "analisis-fuerzas", seccionRelacionada: "A.5.4" },
  { termino: "Análisis modal", definicion: "Procedimiento de análisis dinámico por medio del cual la respuesta dinámica de la estructura se obtiene como la superposición de las respuestas de los diferentes modos, o formas de vibración.", tema: "analisis-fuerzas", seccionRelacionada: "A.5.4" },
  { termino: "Apéndice", definicion: "Es un elemento no estructural que sobresale del volumen general de la edificación.", tema: "no-estructurales" },
  { termino: "Armadura", definicion: "Véase cercha.", tema: "sistema-estructural" },
  { termino: "Base", definicion: "Es el nivel en el que los movimientos sísmicos son transmitidos a la estructura o el nivel en el que la estructura, considerada como un oscilador, está apoyada.", tema: "sistema-estructural" },
  { termino: "Capacidad de disipación de energía", definicion: "Es la capacidad que tiene un sistema estructural, un elemento estructural, o una sección de un elemento estructural, de trabajar dentro del rango inelástico de respuesta sin perder su resistencia. Se cuantifica por medio de la energía de deformación que el sistema, elemento o sección es capaz de disipar en ciclos histeréticos consecutivos. Cuando hace referencia al sistema de resistencia sísmica de la edificación como un todo, se define por medio del coeficiente de capacidad de disipación de energía básico R0, el cual después se afecta debido a irregularidades de la estructura y a ausencia de redundancia en el sistema de resistencia sísmica, para obtener el coeficiente de disipación de energía R (R = φa·φp·φr·R0). El grado de capacidad de disipación de energía se clasifica como especial (DES), moderado (DMO) y mínimo (DMI).", tema: "sistema-estructural", seccionRelacionada: "A.3.1.3" },
  { termino: "Capacidad de rotación de la sección", definicion: "Es la capacidad que tiene una sección de un elemento estructural de admitir rotaciones en el rango inelástico sin perder su capacidad de resistir momentos flectores y fuerzas cortantes. Se mide en términos de su capacidad de disipación de energía a la rotación.", tema: "sistema-estructural" },
  { termino: "Carga muerta", definicion: "Es la carga vertical debida a los efectos gravitacionales de la masa, o peso, de todos los elementos permanentes ya sean estructurales o no estructurales. Debe consultarse el Título B de este Reglamento.", tema: "cargas-unidades" },
  { termino: "Carga gravitacional o peso, (M.g)", definicion: "Es el efecto vertical de la aceleración debida a la gravedad sobre la masa, M, de la edificación. M debe ser igual a la masa de la estructura más la masa de los elementos tales como muros divisorios y particiones, equipos permanentes, tanques y sus contenidos, etc. En depósitos y bodegas debe incluirse además un 25 por ciento de la masa que produce la carga viva.", tema: "cargas-unidades" },
  { termino: "Carga viva", definicion: "Es la carga debida al uso de la estructura, sin incluir la carga muerta, fuerza de viento o sismo. Debe consultarse el Título B de este Reglamento.", tema: "cargas-unidades" },
  { termino: "Casa", definicion: "Edificación unifamiliar destinada a vivienda. Esta definición se incluye únicamente para efectos de la aplicación del Título E del Reglamento.", tema: "sistema-estructural" },
  { termino: "Centro de masa del piso", definicion: "Es el lugar geométrico donde estaría localizada, en planta, toda la masa del piso al suponer el diafragma del piso como un cuerpo infinitamente rígido en su propio plano.", tema: "sistema-estructural" },
  { termino: "Centro de rigidez del piso", definicion: "Es el lugar geométrico, localizado en planta y determinado bajo el supuesto de que el diafragma del piso es infinitamente rígido en su propio plano, donde al aplicar una fuerza horizontal, en cualquier dirección, no se presenta rotación del diafragma alrededor de un eje vertical.", tema: "sistema-estructural" },
  { termino: "Cercha", definicion: "Es un conjunto de elementos estructurales unidos entre si, los cuales resisten primordialmente fuerzas axiales.", tema: "sistema-estructural" },
  { termino: "Cerramiento", definicion: "Muro localizado en el paramento del lote de terreno y que se encuentra separado de la edificación en la dirección perpendicular al paramento del lote de terreno, que no hace parte del sistema estructural de soporte de la edificación, y cuya altura no excede 4 metros.", tema: "no-estructurales" },
  { termino: "Coeficiente de amortiguamiento crítico", definicion: "Es, para un sistema elástico, de un grado de libertad con amortiguamiento viscoso, el cociente entre la cantidad de amortiguamiento del sistema y el amortiguamiento mínimo que inhibe toda oscilación.", tema: "analisis-fuerzas" },
  { termino: "Coeficiente de capacidad de disipación de energía básico, R0", definicion: "Coeficiente que se prescribe para cada sistema estructural de resistencia sísmica, cuyo valor depende del tipo de sistema estructural y de las características de capacidad de disipación de energía propias del material estructural que se utiliza en el sistema. Es una medida de la capacidad de disipación de energía general del sistema de resistencia sísmica cuando los movimientos sísmicos hacen que responda inelásticamente.", tema: "sistema-estructural", seccionRelacionada: "A.3.2" },
  { termino: "Coeficiente de capacidad de disipación de energía, R", definicion: "Coeficiente que corresponde al coeficiente de capacidad de disipación de energía básico, R0, multiplicado por los coeficientes de reducción de capacidad de disipación debido a irregularidades en alzado, φa, irregularidad en planta, φp, y a ausencia de redundancia del sistema estructural de resistencia sísmica, φr. (R = φa·φp·φr·R0).", tema: "sistema-estructural", seccionRelacionada: "A.3.3.3" },
  { termino: "Coincidencia de las losas de entrepiso en la colindancia", definicion: "Se considera que las losas de entrepiso de dos estructuras colindantes coinciden o están en contacto cuando al menos la mitad de la altura de la losa de entrepiso de la edificación cuya licencia de construcción se solicita, coincida en nivel con la losa de entrepiso de la edificación colindante existente.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Construcción sismo resistente", definicion: "Es el tipo de construcción que cumple el objetivo expresado en A.1.2.2, a través de un diseño y una construcción que cumplan los requisitos de la Ley 400 de 1997 y del presente Reglamento.", tema: "profesionales-proceso", seccionRelacionada: "A.1.2.2" },
  { termino: "Constructor", definicion: "Es el profesional, ingeniero civil, arquitecto o constructor en arquitectura e ingeniería, bajo cuya responsabilidad se adelante la construcción de la edificación.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.8" },
  { termino: "Cortante de piso, Vx", definicion: "Es la suma algebraica de las fuerzas sísmicas horizontales que actúan por encima del piso en consideración.", tema: "analisis-fuerzas", seccionRelacionada: "A.3.6.6" },
  { termino: "Cortante en la base, Vs", definicion: "Es la suma algebraica, tomada en la base, de todas las fuerzas sísmicas horizontales del edificio.", tema: "analisis-fuerzas", seccionRelacionada: "A.4.3.1" },
  { termino: "Cuerda", definicion: "Es el elemento de borde de un diafragma, el cual resiste principalmente esfuerzos axiales, en una forma análoga a las aletas de una viga.", tema: "sistema-estructural" },
  { termino: "Deriva de piso", definicion: "Es la diferencia entre los desplazamientos horizontales de los niveles entre los cuales está comprendido el piso.", tema: "deriva-separacion", seccionRelacionada: "A.6.1.2" },
  { termino: "Desempeño de los elementos no estructurales", definicion: "Se denomina desempeño el comportamiento de los elementos no estructurales de la edificación ante la ocurrencia de un sismo que la afecte. El desempeño se clasifica en grado superior, bueno y bajo.\n(a) Grado de desempeño superior — Es aquel en el cual el daño que se presenta en los elementos no estructurales es mínimo y no interfiere con la operación de la edificación en ningún aspecto.\n(b) Grado de desempeño bueno — Es aquel en el cual el daño que se presenta en los elementos no estructurales es totalmente reparable y puede haber alguna interferencia con la operación de la edificación con posterioridad a la ocurrencia del sismo.\n(c) Grado de desempeño bajo — Es aquel en el cual se presentan daños graves en los elementos no estructurales, inclusive no reparables.", tema: "no-estructurales", seccionRelacionada: "A.9.2" },
  { termino: "DES", definicion: "Capacidad especial de disipación de energía.", tema: "sistema-estructural", seccionRelacionada: "A.3.1.3" },
  { termino: "Diafragma", definicion: "Conjunto de elementos estructurales, tal como una losa de entrepiso, que transmite las fuerzas inerciales horizontales a los elementos verticales del sistema de resistencia sísmica. El término diafragma incluye conjuntos arriostrados horizontales. Véase sistema de arriostramiento horizontal.", tema: "sistema-estructural", seccionRelacionada: "A.3.6.8" },
  { termino: "Diagonal", definicion: "Es un elemento estructural que hace parte de un pórtico con diagonales. La diagonal puede ser concéntrica, en pórticos con diagonales de concreto reforzado o de acero estructural, o excéntrica en pórticos de acero estructural.", tema: "sistema-estructural" },
  { termino: "Diagonal concéntrica", definicion: "Es una diagonal cuyos dos extremos llegan a conexiones entre viga y columna.", tema: "sistema-estructural" },
  { termino: "Diagonal excéntrica", definicion: "Es una diagonal en la cual uno de sus extremos llega a la viga en un punto alejado de la conexión entre viga y columna. Solo se utiliza en pórticos de acero estructural con diagonales.", tema: "sistema-estructural" },
  { termino: "Diseñador arquitectónico", definicion: "Es el arquitecto bajo cuya responsabilidad se realizan el diseño y los planos arquitectónicos de la edificación, y quien los firma o rotula.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.3" },
  { termino: "Diseñador de los elementos no estructurales", definicion: "Es el profesional facultado para este fin, bajo cuya responsabilidad se realizan el diseño y los planos de los elementos no estructurales de la edificación, y quien los firma o rotula.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.6" },
  { termino: "Diseñador estructural", definicion: "Es el ingeniero civil, facultado para ese fin, bajo cuya responsabilidad se realiza el diseño y los planos estructurales de la edificación, y quien los firma o rotula.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.4" },
  { termino: "DMO", definicion: "Capacidad moderada de disipación de energía.", tema: "sistema-estructural", seccionRelacionada: "A.3.1.3" },
  { termino: "DMI", definicion: "Capacidad mínima de disipación de energía.", tema: "sistema-estructural", seccionRelacionada: "A.3.1.3" },
  { termino: "Ductilidad", definicion: "Capacidad que tiene un material estructural de resistir, sin fallar, deformaciones que lleven al material estructural más allá del límite elástico, o límite donde las deformaciones son linealmente proporcionales al esfuerzo o fuerza aplicada. (Véase capacidad de disipación de energía, pues muchas veces estos términos son confundidos.) Dependiendo del parámetro que describe las deformaciones, la ductilidad puede hacer referencia, entre otras, a:\n(a) Ductilidad de curvatura — cuando la ductilidad se mide con respecto a la curvatura de la sección del elemento estructural. La curvatura se define como el cociente entre el momento flector aplicado y la rigidez de la sección,\n(b) Ductilidad de rotación — cuando la ductilidad se mide con respecto a la rotación que tiene un sector longitudinal del elemento estructural. La rotación se define como la pendiente de la línea elástica del elemento medida con respecto a la posición original del eje longitudinal del elemento,\n(c) Ductilidad de desplazamiento — cuando la ductilidad se mide con respecto al desplazamiento o deflexión que tiene el elemento estructural. El desplazamiento se mide con respecto a la posición original del eje longitudinal del elemento, y\n(d) Ductilidad de deformación — cuando la ductilidad se mide con respecto a la deformación unitaria de una fibra paralela al eje neutro de la sección.", tema: "sistema-estructural" },
  { termino: "Edificación", definicion: "Es una construcción cuyo uso primordial es la habitación u ocupación por seres humanos.", tema: "sistema-estructural" },
  { termino: "Edificación de atención a la comunidad", definicion: "Son los equipamentos urbanos necesarios para atender emergencias, preservar la salud y la seguridad de las personas, tales como estaciones de bomberos, cuarteles de policía y fuerzas militares, instalaciones de salud, sedes de organismos operativos de emergencias, entre otros.", tema: "amenaza-suelo" },
  { termino: "Edificaciones indispensables", definicion: "Son aquellos equipamentos urbanos de atención a la comunidad que deben funcionar durante y después de un sismo, cuya operación no puede ser trasladada rápidamente a un lugar alterno, tales como hospitales y centrales de operación y control de líneas vitales.", tema: "amenaza-suelo", seccionRelacionada: "A.1.3.10" },
  { termino: "Efectos gravitacionales", definicion: "Véase peso.", tema: "cargas-unidades" },
  { termino: "Elemento o miembro estructural", definicion: "Componente del sistema estructural de la edificación. En las estructuras metálicas los dos términos no son sinónimos pues un miembro está compuesto por elementos. Por ejemplo en una viga con sección en I, la viga en sí es el miembro estructural, y su alma y alas son elementos del miembro.", tema: "sistema-estructural" },
  { termino: "Elemento colector", definicion: "Es un elemento que sirve para transmitir las fuerzas inerciales generadas dentro del diafragma, hasta los elementos del sistema de resistencia sísmica.", tema: "sistema-estructural", seccionRelacionada: "A.3.6.5" },
  { termino: "Elemento de borde", definicion: "Es un elemento que se coloca en los bordes de las aberturas, en el perímetro de los muros de cortante o en el perímetro de los diafragmas.", tema: "sistema-estructural" },
  { termino: "Elementos flexibles (o sistemas flexibles)", definicion: "Son aquellos cuya deformación, al ser solicitados por una fuerza horizontal, es significativamente mayor que la de los elementos adyacentes del sistema.", tema: "sistema-estructural" },
  { termino: "Elementos no estructurales", definicion: "Elementos o componentes de la edificación que no hacen parte de la estructura o su cimentación. Véase acabados.", tema: "no-estructurales" },
  { termino: "Efectos ortogonales", definicion: "Son los que se producen en los elementos estructurales que pertenecen, simultáneamente, a sistemas resistentes situados en dos ejes ortogonales, cuando las fuerzas sísmicas actúan en una dirección distinta a la de estos dos ejes.", tema: "analisis-fuerzas", seccionRelacionada: "A.3.6.3" },
  { termino: "Efectos P-Delta", definicion: "Son los efectos de segundo orden en los desplazamientos horizontales y fuerzas internas de la estructura, causados por la acción de las cargas verticales de la edificación al verse desplazadas horizontalmente.", tema: "analisis-fuerzas", seccionRelacionada: "A.6.2.3" },
  { termino: "Espectro", definicion: "Es la colección de valores máximos, ya sea de aceleración, velocidad o desplazamiento, que tienen los sistemas de un grado de libertad durante un sismo.", tema: "analisis-fuerzas", seccionRelacionada: "A.2.6" },
  { termino: "Espectro de diseño", definicion: "Es el espectro correspondiente a los movimientos sísmicos de diseño.", tema: "analisis-fuerzas", seccionRelacionada: "A.2.6" },
  { termino: "Espectro del umbral de daño", definicion: "Es el espectro correspondiente a los movimientos sísmicos al nivel del umbral de daño.", tema: "analisis-fuerzas", seccionRelacionada: "A.12.3" },
  { termino: "Estructura", definicion: "Es un ensamblaje de elementos, diseñado para soportar las cargas gravitacionales y resistir las fuerzas horizontales. Las estructuras pueden ser catalogadas como estructuras de edificaciones o estructuras diferentes a las de las edificaciones.", tema: "sistema-estructural" },
  { termino: "Falla geológica", definicion: "Ruptura, o zona de ruptura, en la roca de la corteza terrestre cuyos lados han tenido movimientos paralelos al plano de ruptura.", tema: "amenaza-suelo" },
  { termino: "Falla geológica activa", definicion: "Falla geológica que se considera que es capaz de producir movimientos sísmicos. Para efectos del presente Reglamento una falla activa es aquella que haya tenido actividad sismogénica recurrente durante el Cuaternario (véase A.2.9.3.1).", tema: "amenaza-suelo", seccionRelacionada: "A.2.9.3.1" },
  { termino: "Fuerzas mayoradas", definicion: "Son las fuerzas que han sido multiplicadas por sus respectivos coeficientes de carga, tal como los define B.2.1 de este Reglamento.", tema: "cargas-unidades", seccionRelacionada: "B.2.1" },
  { termino: "Fuerzas sísmicas", definicion: "Son los efectos inerciales causados por la aceleración del sismo, expresados como fuerzas para ser utilizadas en el análisis y diseño de la estructura.", tema: "analisis-fuerzas", seccionRelacionada: "A.3.1.1" },
  { termino: "Grupo de uso", definicion: "Clasificación de las edificaciones según su importancia para la atención y recuperación de las personas que habitan en una región que puede ser afectada por un sismo, o cualquier tipo de desastre.", tema: "amenaza-suelo", seccionRelacionada: "A.2.5" },
  { termino: "Histéresis", definicion: "Fenómeno por medio del cual dos, o más, propiedades físicas se relacionan de una manera que depende de la historia de su comportamiento previo. En general hace referencia al comportamiento de los materiales estructurales cuando se ven sometidos a deformaciones o esfuerzos que están fuera del rango lineal, o elástico, de comportamiento. Una gran parte de la energía que es capaz de disipar el material estructural en el rango inelástico de respuesta se asocia con el área comprendida dentro de los ciclos de histéresis.", tema: "sistema-estructural" },
  { termino: "Índice de deriva", definicion: "Es la deriva del piso dividida por la altura del mismo.", tema: "deriva-separacion", seccionRelacionada: "A.6.4" },
  { termino: "Ingeniero geotecnista", definicion: "Es el ingeniero civil, quien firma el estudio geotécnico, bajo cuya responsabilidad se realizan los estudios geotécnicos o de suelos, por medio de los cuales se fijan los parámetros de diseño de la cimentación, los efectos de amplificación de la onda sísmica causados por el tipo y estratificación del suelo subyacente a la edificación, y la definición de los parámetros del suelo que se deben utilizar en la evaluación de los efectos de interacción suelo-estructura.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.2" },
  { termino: "Instalaciones indispensables", definicion: "Véase edificaciones indispensables.", tema: "amenaza-suelo", seccionRelacionada: "A.1.3.10" },
  { termino: "Interacción suelo-estructura", definicion: "Es el efecto que tienen en la respuesta estática y dinámica de la estructura las propiedades de rigidez del suelo que da apoyo a la edificación, en conjunto con las propiedades de rigidez de la cimentación y de la estructura.", tema: "amenaza-suelo", seccionRelacionada: "A.7.1" },
  { termino: "Interventor", definicion: "Es el profesional, ingeniero civil, arquitecto o constructor en arquitectura e ingeniería, que representa al propietario durante la construcción de la edificación y bajo cuya responsabilidad se verifica que ésta se adelante de acuerdo con todas las reglamentaciones correspondientes y siguiendo los planos, diseños y especificaciones realizados por los diseñadores. Véase supervisión técnica. La Interventoría incluye igualmente actividades de cuantificación de obra y puede extenderse a tareas administrativas.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.9" },
  { termino: "Licencia de construcción", definicion: "Acto por medio del cual se autoriza, a solicitud del interesado, la realización de obras en un predio con construcciones, cualquiera que ellas sean, acordes con el plan de ordenamiento territorial y las normas urbanísticas del distrito o municipio.", tema: "profesionales-proceso" },
  { termino: "Licuación", definicion: "Respuesta de los suelos sometidos a vibraciones, en la cual éstos se comportan como un fluido denso y no como una masa de suelo húmeda.", tema: "amenaza-suelo" },
  { termino: "Líneas vitales", definicion: "Infraestructura básica de redes, tuberías o elementos conectados o continuos, que permite la movilización de energía eléctrica, aguas, combustibles, información y el transporte de personas o productos, esencial para realizar con eficiencia y calidad las actividades de la sociedad.", tema: "amenaza-suelo" },
  { termino: "Mampostería estructural", definicion: "Véanse las Definiciones en el Título D de éste Reglamento.", tema: "sistema-estructural" },
  { termino: "Masa", definicion: "Cantidad de materia que posee un cuerpo. En el Sistema Internacional de Medidas (SI) se expresa en kilogramos, kg.", tema: "cargas-unidades" },
  { termino: "Método de la fuerza horizontal equivalente", definicion: "Es el método de análisis sísmico en el cual los efectos de los movimientos sísmicos de diseño se expresan por medio de unas fuerzas horizontales estáticas equivalentes.", tema: "analisis-fuerzas", seccionRelacionada: "A.4" },
  { termino: "Método del análisis dinámico elástico", definicion: "Es el método de análisis sísmico en el cual los efectos de los movimientos sísmicos de diseño se determinan por medio de la solución de las ecuaciones de equilibrio dinámico, considerando que las propiedades de rigidez de la estructura permanecen dentro del rango de respuesta lineal o elástica.", tema: "analisis-fuerzas", seccionRelacionada: "A.5.4" },
  { termino: "Método del análisis dinámico inelástico", definicion: "Es el método de análisis sísmico en el cual los efectos de los movimientos sísmicos de diseño se determinan por medio de la solución de las ecuaciones de equilibrio dinámico, considerando que las propiedades de rigidez de la estructura se salen del rango de respuesta lineal o elástica.", tema: "analisis-fuerzas", seccionRelacionada: "A.5" },
  { termino: "Microzonificación sísmica", definicion: "División de una región o de un área urbana, en zonas más pequeñas que presentan un cierto grado de similitud en la forma como se ven afectados los movimientos sísmicos, dadas las características de los estratos de suelo subyacente.", tema: "amenaza-suelo", seccionRelacionada: "A.2.9" },
  { termino: "Modos de vibración", definicion: "Son las diferentes formas de vibración propias de la estructura. A cada modo de vibración corresponde una frecuencia de vibración propia. La respuesta dinámica de la estructura, en el rango elástico, se puede expresar como la superposición de los efectos de los diferentes modos. Una estructura tiene tantos modos de vibración, como grados de libertad tenga.", tema: "analisis-fuerzas", seccionRelacionada: "A.5.4" },
  { termino: "Modo fundamental", definicion: "Es el modo de vibración correspondiente al período fundamental de la estructura en la dirección horizontal de interés.", tema: "analisis-fuerzas", seccionRelacionada: "A.5.4" },
  { termino: "Movimientos sísmicos de diseño", definicion: "Es una caracterización de los movimientos del terreno, en el sitio donde se encuentra localizada la edificación, que se producirían como consecuencia de la ocurrencia del sismo de diseño.", tema: "amenaza-suelo", seccionRelacionada: "A.2.2" },
  { termino: "Movimientos sísmicos para el umbral de daño", definicion: "Es una caracterización de los movimientos del terreno, en el sitio donde se encuentra localizada la edificación, que se producirían como consecuencia de la ocurrencia del sismo correspondiente al umbral de daño.", tema: "amenaza-suelo", seccionRelacionada: "A.12" },
  { termino: "Movimiento telúrico", definicion: "Movimiento de la corteza terrestre. Véase sismo.", tema: "amenaza-suelo" },
  { termino: "Muro de carga", definicion: "Es un muro estructural, continuo hasta la cimentación, que soporta principalmente cargas verticales.", tema: "sistema-estructural" },
  { termino: "Muro de cortante", definicion: "Véase muro estructural.", tema: "sistema-estructural" },
  { termino: "Muro divisorio o partición", definicion: "Es un muro que no cumple una función estructural y que se utiliza para dividir espacios.", tema: "no-estructurales" },
  { termino: "Muro estructural", definicion: "Es un muro, de carga o no, que se diseña para resistir fuerzas horizontales, de sismo o de viento, paralelas al plano del muro.", tema: "sistema-estructural" },
  { termino: "Muro no estructural", definicion: "Véase muro divisorio.", tema: "no-estructurales" },
  { termino: "Nivel (medido desde la base) de un piso en la colindancia", definicion: "Es la suma de las alturas de piso en la colindancia medidas desde la base hasta la parte superior del piso bajo estudio.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Número de pisos aéreos de la edificación", definicion: "Para efectos de la aplicación de la reglamentación de separación entre edificaciones de A.6.5.2, el máximo número de pisos aéreos de una edificación corresponde al número de losas de entrepiso aéreas, contando dentro de ellas la cubierta como una losa de entrepiso, y sin contar los sótanos. Una losa de entrepiso aérea es aquella que no esta en contacto con el terreno en ningún punto. Cuando un piso tenga más de 6 m de altura, se contará como dos pisos para efectos de calcular el número de pisos aéreos de la edificación.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Número de pisos aéreos en la colindancia", definicion: "Corresponde al número de pisos aéreos de la edificación, que se extienden hasta el paramento del lote de terreno en la zona de colindancia bajo estudio. Cuando un piso en la colindancia tenga más de 6 m de altura, se contará como dos pisos para efectos de calcular el número de pisos aéreos de la edificación en la colindancia.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Perfil de suelo", definicion: "Son los diferentes estratos de suelo existentes debajo del sitio de la edificación.", tema: "amenaza-suelo", seccionRelacionada: "A.2.4.2" },
  { termino: "Período de vibración, T", definicion: "Es el tiempo que transcurre dentro de un movimiento armónico ondulatorio, o vibratorio, para que éste se repita.", tema: "analisis-fuerzas", seccionRelacionada: "A.4.2" },
  { termino: "Período de vibración fundamental", definicion: "Es el mayor período de vibración de la estructura en la dirección horizontal de interés.", tema: "analisis-fuerzas", seccionRelacionada: "A.4.2" },
  { termino: "Peso", definicion: "Efecto gravitacional sobre la masa. Se obtiene de multiplicar la masa en kg, por la aceleración debida a la gravedad, g (g = 9.8 m/s²). Se expresa en newtons, N (1 N = 1 kg · 1 m/s²).", tema: "cargas-unidades" },
  { termino: "Piso", definicion: "Es el espacio comprendido entre dos niveles de una edificación. Piso x es el que está debajo del nivel x.", tema: "deriva-separacion" },
  { termino: "Piso flexible", definicion: "Es aquel en el cual la rigidez ante fuerzas horizontales, del sistema de resistencia sísmica, es menor que el 70% de la rigidez ante fuerzas horizontales, del sistema de resistencia sísmica, del piso inmediatamente superior.", tema: "sistema-estructural", seccionRelacionada: "A.3.3.5" },
  { termino: "Piso débil", definicion: "Es aquel en el cual la resistencia ante fuerzas horizontales, del sistema de resistencia sísmica, del piso es menor que el 70% de la resistencia ante fuerzas horizontales, del sistema de resistencia sísmica, del piso inmediatamente superior.", tema: "sistema-estructural", seccionRelacionada: "A.3.3.5" },
  { termino: "Plastificación progresiva, método de", definicion: "Método de análisis no lineal estático conocido en inglés con el nombre de “push-over” (Véase Apéndice A-3).", tema: "analisis-fuerzas", seccionRelacionada: "A-3" },
  { termino: "Pórtico", definicion: "Es un conjunto de vigas, columnas y, en algunos casos, diagonales, todos ellos interconectados entre si por medio de conexiones o nudos que pueden ser, o no, capaces de transmitir momentos flectores de un elemento a otro. Dependiendo de sus características tiene las siguientes denominaciones:", tema: "sistema-estructural" },
  { termino: "Pórtico arriostrado", definicion: "Véase la definición de pórtico con diagonales.", tema: "sistema-estructural" },
  { termino: "Pórtico-cercha de acero resistente a momentos", definicion: "Pórtico en el que las vigas son cerchas cuyo tramo central, denominado segmento especial, se diseña para que actúe como elemento disipador de energía, de modo que todos los elementos diferentes al segmento especial permanezcan en el rango elástico.", tema: "sistema-estructural" },
  { termino: "Pórtico con diagonales", definicion: "Pórtico compuesto por vigas, columnas y diagonales excéntricas, o concéntricas, que se utiliza primordialmente para resistir fuerzas horizontales. Sus elementos trabajan principalmente deformándose axialmente, como en una cercha. Sus nudos pueden, o no, ser capaces de transmitir momentos flectores, dependiendo del material estructural que se emplee.", tema: "sistema-estructural" },
  { termino: "Pórtico con diagonales concéntricas", definicion: "Es un pórtico con diagonales en el cual éstas llegan a los nudos conformados por las conexiones entre vigas y columnas.", tema: "sistema-estructural" },
  { termino: "Pórtico con diagonales excéntricas", definicion: "Es un pórtico, de acero estructural, con diagonales que cumple los requisitos presentados en el Capítulo F.3.", tema: "sistema-estructural" },
  { termino: "Pórtico de acero con diagonales restringidas a pandeo", definicion: "Es un pórtico con diagonales cuyo pandeo se restringe mediante el empleo de camisas rellenas de concreto.", tema: "sistema-estructural" },
  { termino: "Pórtico espacial", definicion: "Es un sistema estructural tridimensional, que no tiene muros de carga, compuesto por elementos interconectados de tal manera que el conjunto actúe como una unidad, con o sin la ayuda de diafragmas horizontales o sistemas de arriostramiento horizontal. (Véase pórtico plano).", tema: "sistema-estructural" },
  { termino: "Pórtico losa-columna", definicion: "Es un sistema estructural tridimensional aporticado en el cual las losas cumplen la función de las vigas. Este sistema tiene numerosas restricciones impuestas por el Reglamento en su uso. Véase reticular cedulado.", tema: "sistema-estructural" },
  { termino: "Pórtico no arriostrado", definicion: "Es un pórtico resistente a momentos que soporta las fuerzas horizontales por medio de momentos flectores en sus elementos, y que no tiene diagonales ni muros estructurales.", tema: "sistema-estructural" },
  { termino: "Pórtico no resistente a momentos", definicion: "Es un pórtico cuyas conexiones no son resistentes a momentos y que por lo tanto es inestable ante una solicitación de fuerzas horizontales, a menos que la responsabilidad de la resistencia ante estas fuerzas sea atendida por diagonales dentro del mismo pórtico o por conjuntos de elemento estructurales, tales como muros estructurales o pórticos con diagonales.", tema: "sistema-estructural" },
  { termino: "Pórtico para carga verticales", definicion: "Es un pórtico espacial diseñado para resistir únicamente cargas verticales.", tema: "sistema-estructural" },
  { termino: "Pórtico plano", definicion: "Es un pórtico en el cual todos sus elementos están contenidos dentro de un plano vertical. Este tipo de pórticos no puede utilizarse a menos que existan elementos estructurales que restrinjan los desplazamientos en la dirección perpendicular al plano del pórtico, tales como otros pórticos o muros estructurales y que exista un diafragma que amarre horizontalmente el conjunto. (Véase A.3.1.5) Los enlaces entre pórticos planos a través de la viguetería del sistema de entrepiso no se consideran adecuados para efectos de restringir los desplazamientos en la dirección perpendicular al plano de pórtico, caso en el cual deben disponerse vigas paralelas a la viguetería que enlacen las columnas y conformen un pórtico espacial.", tema: "sistema-estructural", seccionRelacionada: "A.3.1.5" },
  { termino: "Pórtico resistente a momentos", definicion: "Es un pórtico espacial en el cual sus miembros y nudos son capaces de resistir las fuerzas, principalmente, por flexión.", tema: "sistema-estructural" },
  { termino: "Pórtico resistente a momentos, sin capacidad de disipación de energía", definicion: "Es un pórtico de concreto reforzado que no cumple con los requisitos especiales de detallado del refuerzo para lograr un comportamiento dúctil, o que no está dispuesto espacialmente y no tiene resistencia ante fuerzas horizontales en la dirección perpendicular a su propio plano.", tema: "sistema-estructural" },
  { termino: "Pórtico resistente a momentos con capacidad especial de disipación de energía (DES)", definicion: "Es un pórtico espacial diseñado de acuerdo con las disposiciones correspondientes del Capítulo C.21 cuando es de concreto reforzado o del Capítulo F.3 cuando es de acero estructural.", tema: "sistema-estructural" },
  { termino: "Pórtico resistente a momentos con capacidad mínima de disipación de energía (DMI)", definicion: "Es un pórtico espacial diseñado de acuerdo con las disposiciones correspondientes del Capítulo C.21 cuando es de concreto reforzado o de los Capítulos F.1 y F.2 cuando es de acero estructural.", tema: "sistema-estructural" },
  { termino: "Pórtico resistente a momentos con capacidad moderada de disipación de energía (DMO)", definicion: "Es un pórtico espacial, diseñado de acuerdo con las disposiciones correspondientes del Capítulo C.21 cuando es de concreto reforzado, o del Capítulo F.3 cuando es de acero estructural.", tema: "sistema-estructural" },
  { termino: "Probabilidad", definicion: "Es el cociente del número de casos que realmente ocurren, dividido por el número total de casos posibles.", tema: "amenaza-suelo" },
  { termino: "Propietario", definicion: "Para efectos de este Reglamento, es la persona, natural o jurídica, titular de derechos reales principales, poseedor, propietario del derecho de dominio a título de fiducia y los fideicomitentes de las mismas fiducias, a nombre de la cual se expide la licencia de construcción.", tema: "profesionales-proceso" },
  { termino: "Resistencia", definicion: "Es la capacidad útil de una estructura, o de sus miembros, para resistir cargas, dentro de los límites de deformación establecidos en este Reglamento.", tema: "sistema-estructural" },
  { termino: "Reticular celulado", definicion: "Es un tipo de pórtico losa-columna, en el cual la losa trabaja en dos direcciones y es aligerada en las zonas lejanas de las columnas y maciza, o con capiteles, en las zonas aledañas a las columnas. Este sistema tiene numerosas restricciones impuestas por el Reglamento en su uso.", tema: "sistema-estructural" },
  { termino: "Revisor de los diseños", definicion: "Es el ingeniero civil, diferente del diseñador e independiente laboralmente de él, que tiene la responsabilidad de revisar los diseños estructurales y estudios geotécnicos, o el arquitecto, ingeniero civil o mecánico, que revisa los diseños de elementos no estructurales; dentro del trámite de expedición de una licencia de construcción, para constatar que la edificación propuesta cumple con los requisitos exigidos por la Ley 400 de 1997 y el presente Reglamento.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.7" },
  { termino: "Riesgo sísmico", definicion: "Corresponde a la determinación de las consecuencias económicas y sociales, expresada en términos monetarios, o de víctimas, respectivamente, para el sitio de interés en función de su probabilidad de excedencia para un tiempo de exposición dado.", tema: "existentes" },
  { termino: "Rigidez de piso", definicion: "Para un piso x, es el cociente entre el cortante de piso, Vx, y la deriva que éste cortante produce en el piso.", tema: "analisis-fuerzas", seccionRelacionada: "A.3.3.5" },
  { termino: "Riostra", definicion: "Véase diagonal.", tema: "sistema-estructural" },
  { termino: "Riostra del diafragma (riostra transmisora, amarre, elemento colector)", definicion: "Es el elemento de un diafragma, paralelo a la fuerza aplicada, que recoge y transmite el cortante del diafragma a los elementos resistentes verticales o el que distribuye las fuerzas dentro del diafragma. Estos miembros pueden estar sometidos a efectos axiales de tensión o de compresión. Véase sistemas de arriostramiento horizontal.", tema: "sistema-estructural" },
  { termino: "Sello seco registrado", definicion: "Marca realzada que queda colocada sobre un plano de construcción y que reemplaza la firma del diseñador responsable de los diseños expresados en él. La marca que produce debe contener el nombre del profesional, su profesión (ingeniero civil, arquitecto, etc.) y el número de la matricula profesional.", tema: "profesionales-proceso" },
  { termino: "Separación sísmica en la colindancia", definicion: "Es la distancia horizontal en dirección perpendicular al plano vertical levantado sobre el lindero entre los dos lotes de terreno, medida desde la losa de entrepiso de la edificación hasta este plano.", tema: "deriva-separacion", seccionRelacionada: "A.6.5.2" },
  { termino: "Sismo, temblor o terremoto", definicion: "Vibraciones de la corteza terrestre inducidas por el paso de ondas sísmicas provenientes de un lugar o zona donde han ocurrido movimientos súbitos de la corteza terrestre.", tema: "amenaza-suelo" },
  { termino: "Sismo característico", definicion: "Es un sismo definido para una falla activa que tiene una magnitud igual al mejor estimativo que pueda hacerse sobre la máxima magnitud que pueda ocurrir en la falla, pero no menor que la mayor magnitud que haya ocurrido históricamente en la falla.", tema: "amenaza-suelo" },
  { termino: "Sismo de diseño", definicion: "Es la caracterización de los movimientos sísmicos mínimos que deben utilizarse en la realización del diseño sismo resistente. Para efectos del presente Reglamento, es un sismo cuyos efectos en el lugar de interés tienen una probabilidad de sólo diez por ciento de ser excedidos en un lapso de cincuenta años, lo cual conduce a un período promedio de retorno de 475 años. El diseño sismo resistente tiene dentro de sus objetivos la protección de la vida ante la ocurrencia del sismo de diseño.", tema: "amenaza-suelo", seccionRelacionada: "A.2.2" },
  { termino: "Sismo de seguridad limitada", definicion: "Es la caracterización de los movimientos sísmicos que pueden utilizarse alternativamente en la evaluación e intervención de ciertas estructuras existentes. Para efectos del presente Reglamento, es un sismo cuyos efectos en el lugar de interés tienen una probabilidad del veinte por ciento de ser excedidos en un lapso de cincuenta años, lo cual corresponde a un período promedio de retorno de 225 años. Su uso está sometido a las limitaciones dadas en A.10.3.", tema: "existentes", seccionRelacionada: "A.10.3" },
  { termino: "Sismo del umbral de daño", definicion: "Es un sismo cuyos efectos en el lugar de interés tienen una probabilidad del ochenta por ciento de ser excedidos en un lapso de cincuenta años, lo cual conduce a un período promedio de retorno de 31 años. Corresponde a un sismo de intensidad relativamente baja, ante cuya ocurrencia no deben producirse daños a los elementos estructurales y no estructurales, que en caso de que ocurran, éstos deben ser reparables y no deben interferir con el funcionamiento de la edificación.", tema: "amenaza-suelo", seccionRelacionada: "A.12" },
  { termino: "Sistema combinado", definicion: "Es un sistema estructural en el cual las cargas verticales son resistidas por un pórtico, resistente a momentos o no, esencialmente completo, y las fuerzas horizontales son resistidas por muros estructurales o pórticos con diagonales. (Véase A.3.2.1.2).", tema: "sistema-estructural", seccionRelacionada: "A.3.2.1.2" },
  { termino: "Sistema de muros de carga", definicion: "Es un sistema estructural que no dispone de un pórtico esencialmente completo y en el cual las cargas verticales son llevadas hasta la cimentación por los muros de carga y las fuerzas horizontales son resistidas por muros estructurales o pórticos con diagonales. (Véase A.3.2.1.1).", tema: "sistema-estructural", seccionRelacionada: "A.3.2.1.1" },
  { termino: "Sistema de pórtico", definicion: "Es un sistema estructural compuesto por un pórtico espacial, resistente a momentos, esencialmente completo, no arriostrado, que resiste todas las cargas verticales y las fuerzas horizontales. (Véase A.3.2.1.3).", tema: "sistema-estructural", seccionRelacionada: "A.3.2.1.3" },
  { termino: "Sistema dual", definicion: "Es el sistema estructural resultante de la combinación de un pórtico espacial resistente a momentos (de capacidad moderada o alta de disipación de energía) con muros estructurales o pórticos con diagonales, diseñado de acuerdo con A.3.2.1.4.", tema: "sistema-estructural", seccionRelacionada: "A.3.2.1.4" },
  { termino: "Sistema de arriostramiento horizontal", definicion: "Es un sistema de cercha, o armadura, horizontal que cumple las mismas funciones de un diafragma.", tema: "sistema-estructural" },
  { termino: "Sistema de resistencia sísmica", definicion: "Es aquella parte de la estructura que según el diseño aporta la resistencia requerida para soportar los movimientos sísmicos de diseño.", tema: "sistema-estructural", seccionRelacionada: "A.3.1" },
  { termino: "Sistema Internacional de Medidas (SI)", definicion: "El sistema SI se estableció en la Decimoprimera Conferencia Mundial de Pesos y Medidas, que tuvo lugar en Sevres, Francia, en 1960. Por medio del Decreto 1731 de 18 de Septiembre de 1967, el único sistema de medidas permitido en el país es el Sistema Internacional de Medidas SI. El sistema está basado en siete unidades básicas, que son para longitud el metro (m), para masa el kilogramo (kg), para tiempo el segundo (s), para corriente eléctrica el amperio (A), para temperatura el kelvin (K), para intensidad luminosa el candela (cd) y para cantidad de substancia el mol (mol).\nPara efectos del presente Reglamento se utilizan las siguientes unidades:\nUnidades básicas — para distancia el metro (m), para masa el kilogramo (kg), y para tiempo el segundo (s).\nUnidades suplementarias — para ángulo plano el radian (rad)\nUnidades derivadas — para frecuencia el hertz (Hz) [1 Hz = 1 s⁻¹], para fuerza el newton (N) [1 N = 1 kg · m/s²], para esfuerzo, o fuerza por unidad de área, el pascal (Pa) [1 Pa = 1 N/m²], y para energía o trabajo el joule (J) [1 J = N · m]", tema: "cargas-unidades", seccionRelacionada: "A.1.7" },
  { termino: "Solicitaciones", definicion: "Son las fuerzas u otras acciones que afectan la estructura, dentro de las cuales se cuentan: los efectos gravitacionales sobre su propia masa, o peso propio, las cargas generadas por los elementos no estructurales, por sus ocupantes y sus posesiones, los efectos ambientales tales como el viento o el sismo, los asentamientos diferenciales, y los cambios dimensionales causados por variaciones en la temperatura o efectos reológicos de los materiales. En general corresponden a todo lo que puede afectar la estructura.", tema: "cargas-unidades" },
  { termino: "Supervisión técnica", definicion: "Es la verificación de que la construcción de la estructura de la edificación se adelante de acuerdo con los diseños, planos y especificaciones realizadas por el diseñador estructural. Así mismo, que los elementos no estructurales se construyan siguiendo los diseños, planos, y especificaciones realizadas por el diseñador de elementos no estructurales, de acuerdo con el grado de desempeño requerido.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.9" },
  { termino: "Supervisor técnico", definicion: "Es el profesional, ingeniero civil, arquitecto o constructor en arquitectura e ingeniería, bajo cuya responsabilidad se realiza la supervisión técnica. El alcance de la supervisión técnica está definido en el Título I de este Reglamento. La supervisión técnica puede ser realizada por el mismo profesional que realiza la interventoría. Véase interventor.", tema: "profesionales-proceso", seccionRelacionada: "A.1.3.9" },
  { termino: "Temblor, terremoto", definicion: "Véase sismo.", tema: "amenaza-suelo" },
  { termino: "Umbral de daño", definicion: "Corresponde al nivel de movimiento sísmico a partir del cual se pueden presentar daños a los elementos estructurales y no estructurales.", tema: "amenaza-suelo", seccionRelacionada: "A.12" },
  { termino: "Velocidad de la onda de cortante", definicion: "Es la velocidad con que se desplaza la onda sísmica de cortante dentro de un suelo.", tema: "amenaza-suelo", seccionRelacionada: "A.2.4.3" },
  { termino: "Vulnerabilidad", definicion: "Es la cuantificación del potencial de mal comportamiento de una edificación con respecto a alguna solicitación.", tema: "existentes" },
  { termino: "Zona de amenaza sísmica (baja, intermedia o alta)", definicion: "Son regiones del país donde la amenaza sísmica se considera baja, intermedia o alta, tal como se define en A.2.3. Los requisitos de análisis y diseño estructural varían de una zona a otra.", tema: "amenaza-suelo", seccionRelacionada: "A.2.3" },
];

/** Definiciones de A.13.1 en orden alfabético (sin distinguir mayúsculas ni tildes). */
export const definiciones: readonly Definicion[] = [...DEFINICIONES_SIN_ORDEN].sort((a, b) => colador.compare(a.termino, b.termino));

